            st.push(-operand[i]); 
        } 
        else if (op[i - 1] == "*") { 
            long a = st.top(); 
            st.pop(); 
            st.push(a * operand[i]); 
        } 
        else if (op[i - 1] == "//") { 
            long a = st.top(); 
            st.pop(); 
            st.push(a / operand[i]); 
        } 
        else if (op[i - 1] == "**") { 
            long a = st.top(); 
            st.pop(); 
            st.push(pow(a, operand[i])); 
        } 
    } 
}  long res = 0;  while (!st.empty()) { 
    res += st.top(); 
    st.pop(); 
}  return res;  }

